{"security_risk":"LOW","summary":"Create args.rs with CLI parser","command":"create","path":"/workspace/src/args.rs","file_text":"//! Argument parser ported from `src/argsParser.js`.
//!
//! The parser understands a custom nomnom-style option spec and produces both
//! a `positionalArguments` list and an `options` map. Unknown options are
//! passed through so transforms can consume them.

use std::collections::BTreeMap;
use std::collections::HashMap;

use serde_json::Value;

#[derive(Debug, Clone)]
pub struct OptionSpec {
    pub full: String,
    pub key: String,
    pub display_index: i32,
    pub abbr: Option<char>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<String>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub choices: Option<Vec<String>>,
    pub process: Option<String>,
    pub callback: Option<String>,
    pub required: bool,
}

impl OptionSpec {
    fn from_map(name: &str, map: &serde_json::Map<String, Value>) -> Self {
        let get_str = |k: &str| -> Option<String> {
            map.get(k).and_then(|v| v.as_str()).map(|s| s.to_string())
        };
        let get_bool = |k: &str| -> Option<bool> { map.get(k).and_then(|v| v.as_bool()) };
        let get_number = |k: &str| -> Option<Value> {
            map.get(k).cloned()
        };

        OptionSpec {
            full: get_str("full").unwrap_or_else(|| name.to_string()),
            key: name.to_string(),
            display_index: map
                .get("display_index")
                .and_then(|v| v.as_i64())
                .map(|v| v as i32)
                .unwrap_or(1000),
            abbr: get_str("abbr").and_then(|s| s.chars().next()),
            flag: get_bool("flag").unwrap_or(false),
            list: get_bool("list").unwrap_or(false),
            default: get_number("default"),
            default_help: get_str("defaultHelp"),
            help: get_str("help"),
            metavar: get_str("metavar"),
            choices: map
                .get("choices")
                .and_then(|v| v.as_array())
                .map(|arr| {
                    arr.iter()
                        .map(|v| match v {
                            Value::Number(n) => n.to_string(),
                            Value::String(s) => s.clone(),
                            _ => v.to_string(),
                        })
                        .collect()
                }),
            process: get_str("process"),
            callback: get_str("callback"),
            required: get_bool("required").unwrap_or(false),
        }
    }
}

#[derive(Debug)]
pub enum ArgError {
    Help(String),
    Version(String),
    MissingValue(String),
    InvalidChoice(String),
    Generic(String),
}

pub struct ArgParser {
    options: Vec<(String, OptionSpec)>,
    by_long: HashMap<String, usize>,
    by_short: HashMap<char, usize>,
    by_long_no: HashMap<String, usize>,
    help_spec: OptionSpec,
}

#[derive(Debug)]
pub struct ParseResult {
    pub positional_arguments: Vec<String>,
    pub options: HashMap<String, Value>,
}

impl ArgParser {
    pub fn new(specs: Vec<(&str, serde_json::Map<String, Value>)>) -> Self {
        let mut options = Vec::new();
        let mut by_long = HashMap::new();
        let mut by_short = HashMap::new();
        let mut by_long_no = HashMap::new();

        for (name, map) in specs {
            let spec = OptionSpec::from_map(name, &map);
            let idx = options.len();
            by_long.insert(format!("--{}", spec.full), idx);
            if let Some(a) = spec.abbr {
                by_short.insert(a, idx);
            }
            if spec.flag {
                by_long_no.insert(format!("--no-{}", spec.full), idx);
            }
            options.push((name.to_string(), spec));
        }

        // Add synthetic --help option, mirroring `prepareOptions` in the JS source.
        let help_spec = OptionSpec {
            full: "help".to_string(),
            key: "help".to_string(),
            display_index: 5,
            abbr: Some('h'),
            flag: false,
            list: false,
            default: None,
            default_help: None,
            help: Some("print this help and exit".to_string()),
            metavar: None,
            choices: None,
            process: None,
            callback: Some("help".to_string()),
            required: false,
        };

        ArgParser {
            options,
            by_long,
            by_short,
            by_long_no,
            help_spec,
        }
    }

    pub fn help_text(&self) -> String {
        format_help_text(&self.options, &self.help_spec)
    }

    pub fn version_text(&self, version: &str) -> String {
        // Mirrors the JS version option callback layout.
        format!(
            "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
            version,
            crate::pkg::read_package_version("@babel/core").unwrap_or_else(|| "?".to_string()),
            crate::pkg::read_package_version("@babel/parser").unwrap_or_else(|| "?".to_string()),
            crate::pkg::read_package_version("flow-parser").unwrap_or_else(|| "?".to_string()),
            crate::pkg::read_package_version("recast").unwrap_or_else(|| "?".to_string()),
        )
    }

    pub fn parse(&self, args: &[String]) -> Result<ParseResult, ArgError> {
        let mut parsed: HashMap<String, Value> = HashMap::new();
        let mut positional: Vec<String> = Vec::new();

        // Seed defaults
        for (name, spec) in &self.options {
            if let Some(default) = &spec.default {
                parsed.insert(name.clone(), default.clone());
            } else if spec.list {
                parsed.insert(name.clone(), Value::Array(Vec::new()));
            }
        }

        // Help option seeded manually so we can match the JS behavior (it is not in
        // the user-provided spec list).
        parsed.entry("help".to_string()).or_insert(Value::Null);

        let mut i = 0;
        while i < args.len() {
            let arg = &args[i];
            if !is_option(arg) {
                if is_numeric(arg) {
                    if let Ok(n) = arg.parse::<i64>() {
                        positional.push(n.to_string());
                    } else {
                        positional.push(arg.clone());
                    }
                } else {
                    positional.push(arg.clone());
                }
                i += 1;
                continue;
            }

            let mut option_name = arg.clone();
            let mut value: Option<String> = None;

            if let Some(eq_idx) = arg.find('=') {
                option_name = arg[..eq_idx].to_string();
                value = Some(arg[eq_idx + 1..].to_string());
            }

            // Resolve which spec we are using.
            let mut spec_idx: Option<usize> = None;
            let mut synthetic = false;

            if let Some(&idx) = self.by_long.get(&option_name) {
                spec_idx = Some(idx);
            } else if option_name.starts_with("--no-") {
                if let Some(&idx) = self.by_long_no.get(&option_name) {
                    spec_idx = Some(idx);
                }
            } else if option_name.starts_with('-') && option_name.len() == 2 {
                let ch = option_name.chars().nth(1).unwrap();
                if let Some(&idx) = self.by_short.get(&ch) {
                    spec_idx = Some(idx);
                }
            }

            let spec: OptionSpec;
            let key: String;
            let is_flag: bool;
            let is_list: bool;
            let process_kind: Option<String>;
            let cb_kind: Option<String>;

            if let Some(idx) = spec_idx {
                let (k, s) = self.options[idx].clone();
                key = k;
                spec = s;
                is_flag = spec.flag;
                is_list = spec.list;
                process_kind = spec.process.clone();
                cb_kind = spec.callback.clone();
            } else {
                // Synthetic "passed along" option
                synthetic = true;
                key = option_name
                    .trim_start_matches('-')
                    .trim_start_matches("no-")
                    .to_string();
                let next_is_option = args.get(i + 1).map(|v| is_option(v)).unwrap_or(false);
                let is_flag_synth = value.is_none()
                    && !parsed.contains_key(&key)
                    && next_is_option;
                let is_list_synth = parsed.contains_key(&key)
                    && !matches!(parsed.get(&key), Some(Value::Bool(_)));
                spec = OptionSpec {
                    full: key.clone(),
                    key: key.clone(),
                    display_index: 0,
                    abbr: None,
                    flag: is_flag_synth,
                    list: is_list_synth,
                    default: None,
                    default_help: None,
                    help: None,
                    metavar: None,
                    choices: None,
                    process: None,
                    callback: None,
                    required: false,
                };
                is_flag = spec.flag;
                is_list = spec.list;
                process_kind = Some("json".to_string());
                cb_kind = None;
            }

            if let Some(cb) = cb_kind {
                match cb.as_str() {
                    "help" => {
                        return Err(ArgError::Help(self.help_text()));
                    }
                    "version" => {
                        return Err(ArgError::Version(crate::VERSION_OUTPUT.to_string()));
                    }
                    _ => {}
                }
            }

            if is_flag {
                let resolved = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(ref v) = value {
                    Value::Bool(v == "1")
                } else {
                    Value::Bool(true)
                };
                parsed.insert(key, resolved);
            } else {
                let mut consumed_value: Option<String> = value.clone();
                if consumed_value.is_none()
                    && i + 1 < args.len()
                    && !is_option(&args[i + 1])
                {
                    consumed_value = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = consumed_value {
                    let final_value = match process_kind.as_deref() {
                        Some("Number") => match v.parse::<i64>() {
                            Ok(n) => Value::Number(serde_json::Number::from(n)),
                            Err(_) => Value::String(v),
                        },
                        Some("json") => match serde_json::from_str::<Value>(&v) {
                            Ok(parsed_value) => parsed_value,
                            Err(_) => Value::String(v),
                        },
                        _ => Value::String(v),
                    };
                    if is_list {
                        let entry = parsed.entry(key).or_insert(Value::Array(Vec::new()));
                        if let Value::Array(arr) = entry {
                            arr.push(final_value);
                        }
                    } else {
                        parsed.insert(key, final_value);
                    }
                } else {
                    parsed.insert(key, Value::Null);
                }
            }
            i += 1;
        }

        // Validate choices
        for (name, spec) in &self.options {
            if let Some(choices) = &spec.choices {
                if let Some(v) = parsed.get(name) {
                    let v_str = match v {
                        Value::String(s) => s.clone(),
                        Value::Number(n) => n.to_string(),
                        other => other.to_string(),
                    };
                    if !choices.iter().any(|c| c == &v_str) {
                        return Err(ArgError::InvalidChoice(format!(
                            "Error: --{} must be one of the values {}",
                            spec.full,
                            choices.join(",")
                        )));
                    }
                }
            }
            if spec.required {
                let present = parsed.get(name).map(|v| !v.is_null()).unwrap_or(false);
                if !present {
                    return Err(ArgError::Generic(format!(
                        "Error: --{} is required",
                        spec.full
                    )));
                }
            }
        }

        Ok(ParseResult {
            positional_arguments: positional,
            options: parsed,
        })
    }
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value.len() > 1
}

fn is_numeric(value: &str) -> bool {
    !value.is_empty() && value.chars().all(|c| c.is_ascii_digit())
}

fn format_help_text(
    options: &[(String, OptionSpec)],
    help_spec: &OptionSpec,
) -> String {
    // Include the synthetic help option in the display list, exactly like the
    // JS implementation.
    let mut all: Vec<&OptionSpec> = options.iter().map(|(_, s)| s).collect();
    all.push(help_spec);
    let mut sorted = all.into_iter().collect::<Vec<_>>();
    sorted.sort_by_key(|s| s.display_index);

    let mut body = format_help_header();
    for spec in sorted {
        body.push_str(&format_option_line(spec));
        body.push('\n');
    }
    body.trim_start_matches('\n').to_string()
}

fn format_help_header() -> String {
    "\nUsage: jscodeshift [OPTION]... PATH...\n\
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n\
  or:  jscodeshift [OPTION]... -t URL PATH...\n\
  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\
\n\
Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.\n\
If --stdin is set, each line of the standard input is used as a path.\n\
\n\
Options:\n\
\"...\" behind an option means that it can be supplied multiple times.\n\
All options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\
\n"
        .to_string()
}

fn format_option_line(option: &OptionSpec) -> String {
    let mut text = String::from("  ");
    if let Some(a) = option.abbr {
        text.push_str(&format!("-{}, ", a));
    } else {
        text.push_str("    ");
    }
    text.push_str(&format!(
        "--{}{}",
        if option.flag { "(no-)" } else { "" },
        option.full
    ));
    if let Some(choices) = &option.choices {
        text.push('=');
        text.push_str(&choices.join("|"));
    } else if let Some(metavar) = &option.metavar {
        text.push('=');
        text.push_str(metavar);
    }
    if option.list {
        text.push_str(" ...");
    }

    let has_help_block = option.default_help.is_some()
        || option.default.is_some()
        || option.help.is_some();
    if has_help_block {
        text.push_str("  ");
        if text.len() < 32 {
            text.push_str(&" ".repeat(32 - text.len()));
        }
        let text_length = text.len();
        if let Some(h) = &option.help {
            text.push_str(h);
        }
        if option.default_help.is_some() || option.default.is_some() {
            if option.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            let def = option
                .default_help
                .clone()
                .or_else(|| option.default.as_ref().map(value_to_default_help));
            if let Some(d) = def {
                text.push_str(&format!("(default: {})", d));
            }
        }
    }
    text
}

fn value_to_default_help(v: &Value) -> String {
    match v {
        Value::String(s) => s.clone(),
        Value::Number(n) => n.to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Null => "null".to_string(),
        Value::Array(arr) => arr
            .iter()
            .map(value_to_default_help)
            .collect::<Vec<_>>()
            .join(","),
        Value::Object(_) => "[object]".to_string(),
    }
}

impl std::fmt::Display for ArgError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ArgError::Help(s) | ArgError::Version(s) | ArgError::MissingValue(s)
            | ArgError::InvalidChoice(s) | ArgError::Generic(s) => write!(f, "{}", s),
        }
    }
}

pub fn spec_options_iter(
    options: &BTreeMap<String, serde_json::Map<String, Value>>,
) -> Vec<(String, serde_json::Map<String, Value>)> {
    options
        .iter()
        .map(|(k, v)| (k.clone(), v.clone()))
        .collect()
}"}

{"security_risk":"LOW","summary":"Create pkg.rs for package utilities","command":"create","path":"/workspace/src/pkg.rs","file_text":"//! Helpers for reading the bundled `jscodeshift` package and any of its
//! declared dependencies. Replicates `utils/requirePackage.js`.

use std::fs;
use std::path::{Path, PathBuf};

pub fn package_root() -> PathBuf {
    // The Rust binary lives in the repo root; the JS package is colocated at
    // `codebase/`. The location can be overridden with `JS_CODESHIFT_DIR`.
    if let Ok(p) = std::env::var("JS_CODESHIFT_DIR") {
        return PathBuf::from(p);
    }
    let exe = std::env::current_exe().expect("current_exe");
    let mut dir = exe.parent().map(Path::to_path_buf).unwrap_or_default();
    if dir.ends_with("target/release") || dir.ends_with("target/debug") {
        if let Some(parent) = dir.parent().and_then(|p| p.parent()) {
            dir = parent.to_path_buf();
        }
    } else if let Some(file_name) = dir.file_name() {
        if file_name == "target" {
            if let Some(parent) = dir.parent() {
                dir = parent.to_path_buf();
            }
        }
    }
    dir.push("codebase");
    dir
}

pub fn read_package_version(name: &str) -> Option<String> {
    let mut dir = package_root();
    if dir.join("package.json").exists() {
        // Try resolving through node_modules first
        let mut candidate = dir.join("node_modules").join(name);
        if candidate.exists() {
            dir = candidate;
        } else {
            // Walk up looking for the package directory
            while dir.parent().is_some() {
                candidate = dir.join("node_modules").join(name);
                if candidate.exists() {
                    dir = candidate;
                    break;
                }
                if let Some(parent) = dir.parent() {
                    dir = parent.to_path_buf();
                } else {
                    break;
                }
            }
        }
    }
    let pkg_path = dir.join("package.json");
    let content = fs::read_to_string(&pkg_path).ok()?;
    let parsed: serde_json::Value = serde_json::from_str(&content).ok()?;
    if parsed.get("name").and_then(|v| v.as_str()) == Some(name) {
        parsed.get("version").and_then(|v| v.as_str()).map(|s| s.to_string())
    } else {
        None
    }
}

pub fn join_within_package(relative: &str) -> PathBuf {
    let mut p = package_root();
    p.push(relative);
    p
}

pub fn ensure_within_package<P: AsRef<Path>>(path: P) -> PathBuf {
    let root = package_root();
    let path = path.as_ref();
    if path.is_absolute() {
        path.to_path_buf()
    } else {
        root.join(path)
    }
}"}

{"security_risk":"LOW","summary":"Create cli.rs with Options struct","command":"create","path":"/workspace/src/cli.rs","file_text":"//! CLI option definitions. Mirrors the spec declared in `bin/jscodeshift.js`.

use serde_json::{Map, Value};

use crate::args::spec_options_iter;
use crate::args::ArgParser;
use std::collections::BTreeMap;

pub const VERSION: &str = env!("CARGO_PKG_VERSION");

pub fn build_parser() -> ArgParser {
    // Build a JSON description of the option spec matching the JS one.
    // We use JSON so we can express the type of `default` (string, number,
    // array, etc.) and `choices` naturally.
    let mut map: BTreeMap<String, Map<String, Value>> = BTreeMap::new();

    // transform
    map.insert(
        "transform".to_string(),
        json_obj(&[
            ("display_index", Value::from(15)),
            ("abbr", Value::from("t")),
            ("default", Value::from("./transform.js")),
            ("help", Value::from("path to the transform file. Can be either a local path or url")),
            ("metavar", Value::from("FILE")),
            ("required", Value::from(true)),
        ]),
    );

    // cpus
    map.insert(
        "cpus".to_string(),
        json_obj(&[
            ("display_index", Value::from(1)),
            ("abbr", Value::from("c")),
            ("help", Value::from("start at most N child processes to process source files")),
            ("defaultHelp", Value::from("max(all - 1, 1)")),
            ("metavar", Value::from("N")),
            ("process", Value::from("Number")),
        ]),
    );

    // verbose
    map.insert(
        "verbose".to_string(),
        json_obj(&[
            ("display_index", Value::from(16)),
            ("abbr", Value::from("v")),
            ("choices", Value::Array(vec![Value::from(0), Value::from(1), Value::from(2)])),
            ("default", Value::from(0)),
            ("help", Value::from("show more information about the transform process")),
            ("metavar", Value::from("N")),
            ("process", Value::from("Number")),
        ]),
    );

    // dry
    map.insert(
        "dry".to_string(),
        json_obj(&[
            ("display_index", Value::from(2)),
            ("abbr", Value::from("d")),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
            ("help", Value::from("dry run (no changes are made to files)")),
        ]),
    );

    // print
    map.insert(
        "print".to_string(),
        json_obj(&[
            ("display_index", Value::from(11)),
            ("abbr", Value::from("p")),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
            ("help", Value::from("print transformed files to stdout, useful for development")),
        ]),
    );

    // babel
    map.insert(
        "babel".to_string(),
        json_obj(&[
            ("display_index", Value::from(0)),
            ("flag", Value::from(true)),
            ("default", Value::from(true)),
            ("help", Value::from("apply babeljs to the transform file")),
        ]),
    );

    // extensions
    map.insert(
        "extensions".to_string(),
        json_obj(&[
            ("display_index", Value::from(3)),
            ("default", Value::from(default_extensions())),
            ("help", Value::from("transform files with these file extensions (comma separated list)")),
            ("metavar", Value::from("EXT")),
        ]),
    );

    // ignorePattern
    map.insert(
        "ignorePattern".to_string(),
        json_obj(&[
            ("display_index", Value::from(7)),
            ("full", Value::from("ignore-pattern")),
            ("list", Value::from(true)),
            ("help", Value::from("ignore files that match a provided glob expression")),
            ("metavar", Value::from("GLOB")),
        ]),
    );

    // ignoreConfig
    map.insert(
        "ignoreConfig".to_string(),
        json_obj(&[
            ("display_index", Value::from(6)),
            ("full", Value::from("ignore-config")),
            ("list", Value::from(true)),
            ("help", Value::from("ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)")),
            ("metavar", Value::from("FILE")),
        ]),
    );

    // gitignore
    map.insert(
        "gitignore".to_string(),
        json_obj(&[
            ("display_index", Value::from(8)),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
            ("help", Value::from("adds entries the current directory\'s .gitignore file")),
        ]),
    );

    // runInBand
    map.insert(
        "runInBand".to_string(),
        json_obj(&[
            ("display_index", Value::from(12)),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
            ("full", Value::from("run-in-band")),
            ("help", Value::from("run serially in the current process")),
        ]),
    );

    // silent
    map.insert(
        "silent".to_string(),
        json_obj(&[
            ("display_index", Value::from(13)),
            ("abbr", Value::from("s")),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
            ("help", Value::from("do not write to stdout or stderr")),
        ]),
    );

    // parser
    map.insert(
        "parser".to_string(),
        json_obj(&[
            ("display_index", Value::from(9)),
            ("choices", Value::Array(vec![
                Value::from("babel"),
                Value::from("babylon"),
                Value::from("flow"),
                Value::from("ts"),
                Value::from("tsx"),
            ])),
            ("default", Value::from("babel")),
            ("help", Value::from("the parser to use for parsing the source files")),
        ]),
    );

    // parserConfig
    map.insert(
        "parserConfig".to_string(),
        json_obj(&[
            ("display_index", Value::from(10)),
            ("full", Value::from("parser-config")),
            ("help", Value::from("path to a JSON file containing a custom parser configuration for flow or babylon")),
            ("metavar", Value::from("FILE")),
            ("process", Value::from("json")),
        ]),
    );

    // failOnError
    map.insert(
        "failOnError".to_string(),
        json_obj(&[
            ("display_index", Value::from(4)),
            ("flag", Value::from(true)),
            ("help", Value::from("Return a non-zero code when there are errors")),
            ("full", Value::from("fail-on-error")),
            ("default", Value::from(false)),
        ]),
    );

    // version
    map.insert(
        "version".to_string(),
        json_obj(&[
            ("display_index", Value::from(17)),
            ("help", Value::from("print version and exit")),
            ("callback", Value::from("version")),
        ]),
    );

    // stdin
    map.insert(
        "stdin".to_string(),
        json_obj(&[
            ("display_index", Value::from(14)),
            ("help", Value::from("read file/directory list from stdin")),
            ("flag", Value::from(true)),
            ("default", Value::from(false)),
        ]),
    );

    ArgParser::new(spec_options_iter(&map))
}

fn json_obj(items: &[(&str, Value)]) -> Map<String, Value> {
    let mut m = Map::new();
    for (k, v) in items {
        m.insert((*k).to_string(), v.clone());
    }
    m
}

/// Mirrors `DEFAULT_EXTENSIONS.concat(['ts','tsx'])` from @babel/core.
fn default_extensions() -> Value {
    let babel_defaults = vec![
        ".js",
        ".jsx",
        ".es6",
        ".es",
        ".mjs",
        ".ts",
        ".tsx",
    ];
    let mut exts: Vec<String> = babel_defaults
        .into_iter()
        .map(|e| e.trim_start_matches('.').to_string())
        .collect();
    exts.sort();
    Value::String(exts.join(","))
}"}

