{"security_risk":"LOW","summary":"Create ignore.rs for ignore patterns","command":"create","path":"/workspace/src/ignore.rs","file_text":"//! Port of `src/ignoreFiles.js`. Uses `globset` to evaluate the same patterns
//! the JS implementation pushes onto its matchers list.

use std::fs;
use std::path::Path;

use globset::{Glob, GlobMatcher};

pub struct IgnoreRules {
    matcher: GlobMatcher,
    raw_patterns: Vec<String>,
}

impl IgnoreRules {
    pub fn empty() -> Self {
        let matcher = GlobMatcher::new();
        IgnoreRules {
            matcher,
            raw_patterns: Vec::new(),
        }
    }

    pub fn add_from_input<I, S>(&mut self, input: I)
    where
        I: IntoIterator<Item = S>,
        S: AsRef<str>,
    {
        for v in input {
            self.add_pattern(v.as_ref());
        }
    }

    pub fn add_from_file<I, P>(&mut self, files: I)
    where
        I: IntoIterator<Item = P>,
        P: AsRef<Path>,
    {
        for f in files {
            let path = f.as_ref();
            let metadata = match fs::metadata(path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if !metadata.is_file() {
                continue;
            }
            let content = match fs::read_to_string(path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            for line in content.split('\n') {
                let line = line.trim_end_matches('\r');
                self.add_pattern(line);
            }
        }
    }

    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let mut patterns: Vec<String> = Vec::new();
        if !val.contains('/') {
            patterns.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            patterns.push(format!("**/{}**", val));
            patterns.push(format!("{}**", val));
        }
        patterns.push(val.to_string());

        for p in patterns {
            self.raw_patterns.push(p.clone());
            if let Ok(g) = Glob::new(&p) {
                let gm = g.compile_matcher();
                self.matcher.add(gm);
            }
        }
    }

    pub fn should_ignore<P: AsRef<Path>>(&self, path: P) -> bool {
        if self.matcher.is_empty() {
            return false;
        }
        let path_str = path.as_ref().to_string_lossy().to_string();
        if self.matcher.is_match(&path_str) {
            return true;
        }
        // Strip leading `./` and `../` segments to handle relative paths.
        let normalized = strip_traversal(&path_str);
        if normalized != path_str && self.matcher.is_match(&normalized) {
            return true;
        }
        false
    }
}

fn strip_traversal(path: &str) -> String {
    let mut result = path.to_string();
    while result.starts_with("./") || result.starts_with("../") {
        if result.starts_with("./") {
            result = result[2..].to_string();
        } else if result.starts_with("../") {
            result = result[3..].to_string();
        }
    }
    result
}"}

{"security_risk":"LOW","summary":"Create files.rs for file discovery","command":"create","path":"/workspace/src/files.rs","file_text":"//! File discovery helpers ported from `src/Runner.js`.

use std::path::{Path, PathBuf};

use crate::ignore::IgnoreRules;

pub fn collect_files<P: AsRef<Path>>(
    root: P,
    extensions: &[String],
    ignores: &IgnoreRules,
) -> Vec<PathBuf> {
    let mut files = Vec::new();
    let root = root.as_ref();
    let metadata = match std::fs::symlink_metadata(root) {
        Ok(m) => m,
        Err(_) => {
            eprintln!("Skipping path {} which does not exist. ", root.display());
            return files;
        }
    };
    if metadata.is_dir() {
        dir_files(root, extensions, ignores, &mut files);
    } else if extensions.is_empty() || extensions.iter().any(|ext| {
        root.extension()
            .map(|e| format!(".{}", e.to_string_lossy()) == *ext)
            .unwrap_or(false)
    }) {
        if !ignores.should_ignore(root) {
            files.push(root.to_path_buf());
        }
    }
    files
}

fn dir_files(
    dir: &Path,
    extensions: &[String],
    ignores: &IgnoreRules,
    out: &mut Vec<PathBuf>,
) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let path = entry.path();
        let metadata = match std::fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => {
                eprintln!("Skipping path \"{}\" which does not exist.\n", path.display());
                continue;
            }
        };
        if ignores.should_ignore(&path) {
            continue;
        }
        if metadata.is_dir() {
            dir_files(&path, extensions, ignores, out);
        } else if metadata.is_file() {
            if extensions.is_empty()
                || extensions.iter().any(|ext| match path.extension() {
                    Some(e) => format!(".{}", e.to_string_lossy()) == *ext,
                    None => false,
                })
            {
                out.push(path);
            }
        }
    }
}

pub fn extensions_from_csv(value: &str) -> Vec<String> {
    value
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .map(|s| if s.starts_with('.') { s } else { format!(".{}", s) })
        .collect()
}"}

{"security_risk":"LOW","summary":"Create stats.rs for stats aggregation","command":"create","path":"/workspace/src/stats.rs","file_text":"//! Aggregated counters and progress printing. Mirrors the inline `log` object
//! and the `showFileStats`/`showStats` helpers from `src/Runner.js`.

use std::collections::BTreeMap;

use crate::output;

pub struct FileCounters {
    pub error: usize,
    pub ok: usize,
    pub nochange: usize,
    pub skip: usize,
}

impl FileCounters {
    pub fn new() -> Self {
        FileCounters {
            error: 0,
            ok: 0,
            nochange: 0,
            skip: 0,
        }
    }

    pub fn inc(&mut self, status: &str) {
        match status {
            "ok" => self.ok += 1,
            "nochange" => self.nochange += 1,
            "skip" => self.skip += 1,
            "error" => self.error += 1,
            _ => {}
        }
    }
}

pub struct Stats {
    pub counters: FileCounters,
    pub updates: BTreeMap<String, usize>,
}

impl Stats {
    pub fn new() -> Self {
        Stats {
            counters: FileCounters::new(),
            updates: BTreeMap::new(),
        }
    }

    pub fn inc(&mut self, name: &str, quantity: usize) {
        *self.updates.entry(name.to_string()).or_insert(0) += quantity;
    }
}

pub fn log_status(status: &str, msg: &str, verbose: u8) {
    let line = match status {
        "ok" => {
            if verbose >= 2 {
                format!("{}{}", output::ok_tag(), msg)
            } else {
                return;
            }
        }
        "nochange" => {
            if verbose >= 1 {
                format!("{}{}", output::noc_tag(), msg)
            } else {
                return;
            }
        }
        "skip" => {
            if verbose >= 1 {
                format!("{}{}", output::skip_tag(), msg)
            } else {
                return;
            }
        }
        "error" => {
            if verbose >= 0 {
                format!("{}{}", output::err_tag(), msg)
            } else {
                return;
            }
        }
        _ => return,
    };
    print!("{}", output::line_break(&line));
}

pub fn report(file: &str, msg: &str) {
    print!(
        "{}{} {}\n",
        output::rep_tag(),
        file,
        output::line_break(msg)
    );
}

pub fn show_file_stats(counters: &FileCounters) {
    print!(
        "Results: \n{} errors\n{} unmodified\n{} skipped\n{} ok\n",
        output::red(&counters.error.to_string()),
        output::yellow(&counters.nochange.to_string()),
        output::yellow(&counters.skip.to_string()),
        output::green(&counters.ok.to_string()),
    );
}

pub fn show_stats(updates: &BTreeMap<String, usize>) {
    if updates.is_empty() {
        return;
    }
    print!("{}", output::blue("Stats: \n"));
    let names: Vec<&String> = updates.keys().collect();
    for name in names {
        print!("{}: {}\n", name, updates[name]);
    }
}"}

{"security_risk":"LOW","summary":"Create worker.rs for worker management","command":"create","path":"/workspace/src/worker.rs","file_text":"//! Worker subprocess management. Each worker is a long-lived Node.js
//! process executing `bridge/transform-host.js`. Communication uses NDJSON
//! over stdio.

use std::io::{BufRead, BufReader, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::mpsc::{channel, Receiver, Sender};
use std::thread;

use serde_json::Value;

use crate::pkg;

#[derive(Debug)]
pub enum WorkerEvent {
    Ready,
    Status {
        status: String,
        path: String,
        msg: Option<String>,
    },
    Update {
        name: String,
        quantity: usize,
    },
    Report {
        path: String,
        msg: String,
    },
    Source {
        path: String,
        source: String,
    },
    Print {
        path: String,
        source: String,
    },
    Fatal(String),
    Exit(i32),
}

pub struct WorkerHandle {
    pub id: usize,
    stdin: ChildStdin,
    events: Receiver<WorkerEvent>,
    child: Option<Child>,
}

impl WorkerHandle {
    pub fn spawn(id: usize, init_payload: Value) -> std::io::Result<Self> {
        let bridge = pkg::join_within_package("bridge/transform-host.js");
        let mut cmd = Command::new("node");
        cmd.arg(bridge)
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());

        // Force the worker to use the same package as the binary.
        let pkg_root = pkg::package_root();
        let pkg_root_str = pkg_root.to_string_lossy().to_string();
        cmd.env("JS_CODESHIFT_DIR", &pkg_root_str);

        let mut child = cmd.spawn()?;
        let stdin = child.stdin.take().expect("child stdin");
        let stdout = child.stdout.take().expect("child stdout");
        let stderr = child.stderr.take();

        // Forward stderr to parent's stderr.
        if let Some(err) = stderr {
            let _ = thread::spawn(move || {
                let reader = BufReader::new(err);
                for line in reader.lines().flatten() {
                    eprintln!("{}", line);
                }
            });
        }

        let (tx, rx) = channel();
        thread::spawn(move || {
            read_worker(stdout, tx);
        });

        let mut handle = WorkerHandle {
            id,
            stdin,
            events: rx,
            child: Some(child),
        };

        // Send the init command synchronously.
        handle
            .send_json(&serde_json::json!({"type": "init", "payload": init_payload}))
            .expect("send init");

        Ok(handle)
    }

    pub fn send_files(&mut self, files: Vec<String>) -> std::io::Result<()> {
        self.send_json(&serde_json::json!({"type": "files", "files": files}))
    }

    pub fn shutdown(mut self) -> std::io::Result<()> {
        let _ = self.send_json(&serde_json::json!({"type": "shutdown"}));
        if let Some(mut child) = self.child.take() {
            let _ = child.wait();
        }
        Ok(())
    }

    pub fn try_recv(&self) -> Option<WorkerEvent> {
        match self.events.try_recv() {
            Ok(ev) => Some(ev),
            Err(std::sync::mpsc::TryRecvError::Empty) => None,
            Err(std::sync::mpsc::TryRecvError::Disconnected) => None,
        }
    }

    fn send_json(&mut self, payload: &Value) -> std::io::Result<()> {
        let s = payload.to_string();
        self.stdin.write_all(s.as_bytes())?;
        self.stdin.write_all(b"\n")?;
        self.stdin.flush()
    }
}

fn read_worker(stdout: ChildStdout, tx: Sender<WorkerEvent>) {
    let reader = BufReader::new(stdout);
    for line in reader.lines() {
        let line = match line {
            Ok(l) => l,
            Err(_) => break,
        };
        if line.is_empty() {
            continue;
        }
        let parsed: Value = match serde_json::from_str(&line) {
            Ok(v) => v,
            Err(_) => {
                let _ = tx.send(WorkerEvent::Fatal(format!(
                    "worker emitted non-JSON line: {}",
                    line
                )));
                continue;
            }
        };
        let event = match parsed.get("event").and_then(|v| v.as_str()) {
            Some("ready") => WorkerEvent::Ready,
            Some("status") => {
                let status = parsed
                    .get("status")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let path = parsed
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let msg = parsed
                    .get("msg")
                    .and_then(|v| v.as_str())
                    .map(|s| s.to_string());
                WorkerEvent::Status { status, path, msg }
            }
            Some("update") => {
                let name = parsed
                    .get("name")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let quantity = parsed
                    .get("quantity")
                    .and_then(|v| v.as_u64())
                    .unwrap_or(1) as usize;
                WorkerEvent::Update { name, quantity }
            }
            Some("report") => {
                let path = parsed
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let msg = parsed
                    .get("msg")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                WorkerEvent::Report { path, msg }
            }
            Some("source") => {
                let path = parsed
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let source = parsed
                    .get("source")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                WorkerEvent::Source { path, source }
            }
            Some("print") => {
                let path = parsed
                    .get("path")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                let source = parsed
                    .get("source")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                WorkerEvent::Print { path, source }
            }
            Some("fatal") => {
                let error = parsed
                    .get("error")
                    .and_then(|v| v.as_str())
                    .unwrap_or("")
                    .to_string();
                WorkerEvent::Fatal(error)
            }
            Some("exit") => {
                let code = parsed
                    .get("code")
                    .and_then(|v| v.as_i64())
                    .unwrap_or(0) as i32;
                WorkerEvent::Exit(code)
            }
            _ => continue,
        };
        if tx.send(event).is_err() {
            break;
        }
    }
}"}

{"security_risk":"LOW","summary":"Create runner.rs for orchestration","command":"create","path":"/workspace/src/runner.rs","file_text":"//! Main runner. Replicates the orchestration logic of `src/Runner.js`: HTTP
//! transform download, file discovery, ignore handling, worker spawning and
//! chunk scheduling, result aggregation, and the final summary output.

use std::fs;
use std::io::{Read, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use serde_json::{json, Value};

use crate::files;
use crate::ignore::IgnoreRules;
use crate::output;
use crate::pkg;
use crate::stats::{self, Stats};
use crate::worker::{WorkerEvent, WorkerHandle};

pub struct RunOptions {
    pub transform: String,
    pub paths: Vec<String>,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: Vec<String>,
    pub verbose: u8,
    pub run_in_band: bool,
    pub cpus: Option<usize>,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<String>,
    pub fail_on_error: bool,
    pub stdin: bool,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
}

#[derive(Default)]
struct RunnerOutput {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
    stats: std::collections::BTreeMap<String, usize>,
}

pub fn run(options: RunOptions) -> i32 {
    let start_time = Instant::now();
    let available_cpus = std::cmp::max(num_cpus(), 1);
    let cpus = options
        .cpus
        .map(|n| std::cmp::min(available_cpus, n))
        .unwrap_or(available_cpus);

    let mut ignores = IgnoreRules::empty();
    ignores.add_from_input(options.ignore_pattern.iter());
    ignores.add_from_file(options.ignore_config.iter());

    if options.gitignore {
        let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
        ignores.add_from_file(std::iter::once(cwd.join(".gitignore")));
    }

    // Resolve transform file (download if URL).
    let resolved_transform = match resolve_transform(&options.transform) {
        Ok(p) => p,
        Err(err) => {
            eprintln!(
                "{}{} Transform file {} does not exist \n",
                output::bg("ERROR", "41"),
                "",
                options.transform
            );
            eprintln!("{}", err);
            return 1;
        }
    };

    // Discover all files.
    let mut all_files: Vec<PathBuf> = Vec::new();
    for path in &options.paths {
        if path.is_empty() {
            continue;
        }
        let collected = files::collect_files(path, &options.extensions, &ignores);
        all_files.extend(collected);
    }

    if all_files.is_empty() {
        if !options.silent {
            print!("No files selected, nothing to do. \n");
        }
        return 0;
    }

    if !options.silent {
        print!("Processing {} files... \n", all_files.len());
        if !options.run_in_band {
            print!("Spawning {} workers...\n", cpus);
        }
        if options.dry {
            print!("{}Running in dry mode, no files will be written! \n", output::green(""));
        }
    }

    let chunk_size = if options.run_in_band {
        all_files.len()
    } else {
        std::cmp::min(
            (all_files.len() + cpus - 1) / cpus,
            super::CHUNK_SIZE,
        )
    };

    let num_files = all_files.len();
    let mut next_index = 0usize;
    let mut next_chunk = || -> Vec<String> {
        if next_index >= num_files {
            return Vec::new();
        }
        let end = std::cmp::min(next_index + chunk_size, num_files);
        let chunk: Vec<String> = all_files[next_index..end]
            .iter()
            .map(|p| p.to_string_lossy().to_string())
            .collect();
        next_index = end;
        if !options.silent && !options.run_in_band && !chunk.is_empty() {
            print!(
                "Sending {} files to free worker...\n",
                chunk.len()
            );
        }
        chunk
    };

    let init_payload = json!({
        "transform": resolved_transform.to_string_lossy(),
        "babel": options.babel,
        "parser": options.parser,
        "parserConfig": options.parser_config,
        "verbose": options.verbose,
        "dry": options.dry,
        "print": options.print,
    });

    let processes = if options.run_in_band {
        1
    } else {
        std::cmp::min(num_files, cpus)
    };

    let mut workers: Vec<WorkerHandle> = Vec::new();
    for i in 0..processes {
        let w = match WorkerHandle::spawn(i, init_payload.clone()) {
            Ok(w) => w,
            Err(err) => {
                eprintln!("failed to spawn worker: {}", err);
                return 1;
            }
        };
        workers.push(w);
    }

    let mut stats = Stats::new();
    let mut pending = vec![true; workers.len()];
    let mut workers_alive = workers.len();

    // Initial dispatch.
    for (i, worker) in workers.iter_mut().enumerate() {
        let chunk = next_chunk();
        if !chunk.is_empty() {
            if worker.send_files(chunk).is_err() {
                pending[i] = false;
                workers_alive -= 1;
            }
        } else {
            pending[i] = false;
        }
    }

    // Wait for any worker to be ready, then send it more files.
    while workers_alive > 0 {
        let mut progressed = false;
        for (i, worker) in workers.iter_mut().enumerate() {
            if !pending[i] {
                continue;
            }
            let event = match worker.try_recv() {
                Some(ev) => ev,
                None => continue,
            };
            progressed = true;
            match event {
                WorkerEvent::Ready => {
                    let chunk = next_chunk();
                    if !chunk.is_empty() {
                        if worker.send_files(chunk).is_err() {
                            pending[i] = false;
                            workers_alive -= 1;
                        }
                    } else {
                        pending[i] = false;
                        workers_alive -= 1;
                    }
                }
                WorkerEvent::Status { status, path, msg } => {
                    stats.counters.inc(&status);
                    let line = msg.unwrap_or_else(|| path.clone());
                    crate::stats::log_status(&status, &line, options.verbose);
                }
                WorkerEvent::Update { name, quantity } => {
                    stats.inc(&name, quantity);
                }
                WorkerEvent::Report { path: _path, msg } => {
                    crate::stats::report(&_path, &msg);
                }
                WorkerEvent::Source { path, source } => {
                    handle_transformed_source(&path, &source, &options);
                }
                WorkerEvent::Print { path: _path, source } => {
                    if !options.silent {
                        println!("{}", source);
                    }
                    let _ = _path;
                }
                WorkerEvent::Fatal(error) => {
                    eprintln!("worker {}: fatal: {}", worker.id, error);
                }
                WorkerEvent::Exit(_code) => {
                    pending[i] = false;
                    workers_alive -= 1;
                }
            }
        }
        if !progressed {
            std::thread::sleep(std::time::Duration::from_millis(10));
        }
    }

    // Shut down workers.
    for worker in workers.into_iter() {
        let _ = worker.shutdown();
    }

    let elapsed = start_time.elapsed().as_secs_f64();
    if !options.silent {
        print!("All done. \n");
        stats::show_file_stats(&stats.counters);
        stats::show_stats(&stats.updates);
        print!("Time elapsed: {:.3}seconds \n", elapsed);
    }

    if options.fail_on_error && stats.counters.error > 0 {
        return 1;
    }
    0
}

fn handle_transformed_source(path: &str, source: &str, options: &RunOptions) {
    if options.dry {
        return;
    }
    let p = Path::new(path);
    if let Some(parent) = p.parent() {
        let _ = fs::create_dir_all(parent);
    }
    if let Err(err) = atomic_write(p, source) {
        eprintln!(
            "{} {} File writer error: {}",
            output::err_tag(),
            path,
            err
        );
    }
}

fn atomic_write(path: &Path, contents: &str) -> std::io::Result<()> {
    let parent = path
        .parent()
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::Other, "no parent dir"))?;
    let mut tmp = tempfile::NamedTempFile::new_in(parent)?;
    tmp.write_all(contents.as_bytes())?;
    tmp.flush()?;
    tmp.persist(path).map_err(|e| e.error)?;
    Ok(())
}

fn resolve_transform(transform: &str) -> Result<PathBuf, String> {
    if transform.starts_with("http://") || transform.starts_with("https://") {
        return download_transform(transform);
    }
    let p = PathBuf::from(transform);
    if p.exists() {
        return Ok(p);
    }
    // The original does `path.resolve(options.transform)`. We mimic by trying
    // to resolve relative to the working directory first.
    let cwd = std::env::current_dir().unwrap_or_else(|_| PathBuf::from("."));
    let candidate = cwd.join(&p);
    if candidate.exists() {
        return Ok(candidate);
    }
    Err(format!("transform file {} does not exist", transform))
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let pkg_root = pkg::package_root();
    let response = ureq::get(url)
        .call()
        .map_err(|e| format!("failed to fetch {}: {}", url, e))?;
    let mut reader = response.into_reader();
    let mut contents = String::new();
    reader
        .read_to_string(&mut contents)
        .map_err(|e| format!("failed to read response body: {}", e))?;

    let ext = Path::new(url)
        .extension()
        .map(|e| e.to_string_lossy().to_string())
        .unwrap_or_else(|| "js".to_string());
    let mut tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&format!(".{}", ext))
        .tempfile_in(pkg_root)
        .map_err(|e| format!("failed to create temp file: {}", e))?;
    tmp.write_all(contents.as_bytes())
        .map_err(|e| format!("failed to write temp file: {}", e))?;
    tmp.flush()
        .map_err(|e| format!("failed to flush temp file: {}", e))?;
    let (_, path) = tmp
        .keep()
        .map_err(|e| format!("failed to persist temp file: {}", e))?;
    Ok(path)
}

fn num_cpus() -> usize {
    std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1)
}"}

{"security_risk":"LOW","summary":"Create main.rs","command":"create","path":"/workspace/src/main.rs","file_text":"//! Binary entry point. Parses CLI arguments and dispatches to the runner.

mod args;
mod cli;
mod files;
mod ignore;
mod output;
mod pkg;
mod runner;
mod stats;
mod worker;

use std::io::Read;

use serde_json::Value;

use crate::args::ArgError;
use crate::cli::build_parser;
use crate::runner::{run, RunOptions};

pub const VERSION_OUTPUT: &str = concat!("jscodeshift ", env!("CARGO_PKG_VERSION"));

fn main() {
    let parser = build_parser();
    let argv: Vec<String> = std::env::args().skip(1).collect();

    let parsed = match parser.parse(&argv) {
        Ok(p) => p,
        Err(ArgError::Help(text)) => {
            print!("{}", text);
            std::process::exit(0);
        }
        Err(ArgError::Version(text)) => {
            // Replicate JS layout: build with parser versions.
            let version = env!("CARGO_PKG_VERSION");
            let babel = pkg::read_package_version("@babel/core").unwrap_or_else(|| "?".to_string());
            let babylon = pkg::read_package_version("@babel/parser").unwrap_or_else(|| "?".to_string());
            let flow = pkg::read_package_version("flow-parser").unwrap_or_else(|| "?".to_string());
            let recast = pkg::read_package_version("recast").unwrap_or_else(|| "?".to_string());
            print!(
                "jscodeshift: {}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n",
                version, babel, babylon, flow, recast
            );
            let _ = text;
            std::process::exit(0);
        }
        Err(err) => {
            // Errors with exit code 1 go to stderr; the JS implementation
            // routed anything with exit code == 0 to stdout. We mirror that.
            eprintln!("{}", err);
            std::process::exit(1);
        }
    };

    if parsed.positional_arguments.is_empty() && !bool_from(&parsed.options, "stdin") {
        eprintln!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            parser.help_text()
        );
        std::process::exit(1);
    }

    let paths: Vec<String> = if bool_from(&parsed.options, "stdin") {
        read_stdin_paths()
    } else {
        parsed.positional_arguments.clone()
    };

    let transform_raw = string_from(&parsed.options, "transform");
    let transform_abs = if transform_raw.starts_with("http://") || transform_raw.starts_with("https://") {
        transform_raw.clone()
    } else {
        let p = std::path::PathBuf::from(&transform_raw);
        if p.is_absolute() {
            p.to_string_lossy().to_string()
        } else {
            std::env::current_dir()
                .unwrap_or_default()
                .join(&p)
                .to_string_lossy()
                .to_string()
        }
    };

    let extensions_csv = string_from(&parsed.options, "extensions");
    let extensions = extensions_csv
        .split(',')
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .map(|s| if s.starts_with('.') { s } else { format!(".{}", s) })
        .collect();

    let options = RunOptions {
        transform: transform_abs,
        paths,
        dry: bool_from(&parsed.options, "dry"),
        print: bool_from(&parsed.options, "print"),
        babel: bool_from(&parsed.options, "babel"),
        extensions,
        verbose: parsed
            .options
            .get("verbose")
            .and_then(|v| v.as_u64())
            .unwrap_or(0) as u8,
        run_in_band: bool_from(&parsed.options, "runInBand"),
        cpus: parsed
            .options
            .get("cpus")
            .and_then(|v| v.as_u64())
            .map(|n| n as usize),
        silent: bool_from(&parsed.options, "silent"),
        parser: string_from(&parsed.options, "parser"),
        parser_config: parsed
            .options
            .get("parserConfig")
            .and_then(|v| match v {
                Value::String(s) => Some(s.clone()),
                Value::Null => None,
                _ => Some(v.to_string()),
            }),
        fail_on_error: bool_from(&parsed.options, "failOnError"),
        stdin: bool_from(&parsed.options, "stdin"),
        ignore_pattern: vec_from(&parsed.options, "ignorePattern"),
        ignore_config: vec_from(&parsed.options, "ignoreConfig"),
        gitignore: bool_from(&parsed.options, "gitignore"),
    };

    let code = run(options);
    std::process::exit(code);
}

fn read_stdin_paths() -> Vec<String> {
    let mut buffer = String::new();
    if std::io::stdin().read_to_string(&mut buffer).is_err() {
        return Vec::new();
    }
    buffer
        .split('\n')
        .map(|s| s.to_string())
        .filter(|s| !s.is_empty())
        .collect()
}

fn bool_from(map: &std::collections::HashMap<String, Value>, key: &str) -> bool {
    map.get(key)
        .and_then(|v| v.as_bool())
        .unwrap_or(false)
}

fn string_from(map: &std::collections::HashMap<String, Value>, key: &str) -> String {
    map.get(key)
        .and_then(|v| match v {
            Value::String(s) => Some(s.clone()),
            Value::Number(n) => Some(n.to_string()),
            Value::Bool(b) => Some(b.to_string()),
            _ => Some(v.to_string()),
        })
        .unwrap_or_default()
}

fn vec_from(map: &std::collections::HashMap<String, Value>, key: &str) -> Vec<String> {
    map.get(key)
        .and_then(|v| v.as_array())
        .map(|arr| {
            arr.iter()
                .map(|v| match v {
                    Value::String(s) => s.clone(),
                    other => other.to_string(),
                })
                .collect()
        })
        .unwrap_or_default()
}

pub const CHUNK_SIZE: usize = 50;"}

{"security_risk":"LOW","summary":"Create bridge/transform-host.js","command":"create","path":"/workspace/bridge/transform-host.js","file_text":"#!/usr/bin/env node

/**
 * Minimal Node.js worker bridge used by the Rust `jscodeshift` runner.
 *
 * The Rust process spawns this script as a long-lived child process. The
 * worker reads NDJSON commands from stdin and emits NDJSON events to stdout.
 *
 * Supported commands (one JSON object per line):
 *   {type:"init", payload:{transform, babel, parser, parserConfig, verbose, dry, print}}
 *   {type:"files", files:["/abs/path/a.js", ...]}
 *   {type:"shutdown"}
 *
 * Supported events:
 *   {event:"ready"}                       - worker ready for more work
 *   {event:"status", status, path, msg?}  - mirrors the original Worker.js status messages
 *   {event:"update", name, quantity}      - stats counter updates
 *   {event:"report", path, msg}           - transform report() output
 *   {event:"source", path, source}        - transformed source for the Rust process to persist
 *   {event:"print", path, source}         - emitted in --print mode for parent to echo
 *   {event:"fatal", error}                - unrecoverable error during init or processing
 */

'use strict';

const fs = require('fs');
const path = require('path');
const readline = require('readline');

const JS_CODESHIFT_DIR = process.env.JS_CODESHIFT_DIR ||
  path.resolve(__dirname, '..', 'codebase');

// Resolve core jscodeshift entry points relative to the colocated package.
const CORE_PATH = path.join(JS_CODESHIFT_DIR, 'src', 'core.js');
const RUNNER_PATH = path.join(JS_CODESHIFT_DIR, 'src', 'Runner.js');

// Load DEFAULT_EXTENSIONS from @babel/core the same way the original worker did.
const babelCore = require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'core'));

let transform = null;
let parserFromTransform = null;
let jscodeshift = null;
let presetEnv = null;
let verbose = 0;
let dry = false;
let print = false;

function emit(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function emitFatal(message) {
  emit({ event: 'fatal', error: String(message && message.stack || message) });
}

function emitStatus(status, file, msg) {
  const payload = { event: 'status', status, path: file };
  if (msg) payload.msg = `${file} ${msg}`;
  emit(payload);
}

function emitReport(file, msg) {
  emit({ event: 'report', path: file, msg: String(msg) });
}

function setup(tr, babel) {
  if (babel) {
    const presets = [];
    try {
      const mod = require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'preset-env'));
      presetEnv = mod && (mod.default || mod);
    } catch (_) {
      presetEnv = null;
    }
    if (presetEnv) {
      presets.push([presetEnv, { targets: { node: true } }]);
    }
    let secondPreset;
    try {
      secondPreset = /\.tsx?$/.test(tr)
        ? require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'preset-typescript'))
        : require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'preset-flow'));
    } catch (err) {
      throw new Error(`failed to load preset for transform: ${err.message}`);
    }

    const registerMod = require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'register'));
    const register = registerMod.default || registerMod;
    register({
      configFile: false,
      babelrc: false,
      presets: presets.concat([[secondPreset.default || secondPreset, {}]]),
      plugins: [
        require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'plugin-transform-class-properties')),
        require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'plugin-transform-nullish-coalescing-operator')),
        require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'plugin-transform-optional-chaining')),
        require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'plugin-transform-modules-commonjs')),
        require(path.join(JS_CODESHIFT_DIR, 'node_modules', '@babel', 'plugin-transform-private-methods')),
      ].map((m) => m.default || m),
      extensions: [].concat(babelCore.DEFAULT_EXTENSIONS || [], ['.ts', '.tsx']),
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ? module.default : module;
  if (module.parser) {
    const getParser = require(path.join(JS_CODESHIFT_DIR, 'src', 'getParser.js'));
    parserFromTransform = typeof module.parser === 'string'
      ? getParser(module.parser)
      : module.parser;
  }
}

function prepareJscodeshift(options) {
  const getParser = require(path.join(JS_CODESHIFT_DIR, 'src', 'getParser.js'));
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function stats(name, quantity) {
  if (typeof quantity !== 'number') quantity = 1;
  emit({ event: 'update', name, quantity });
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = String(trace).split('\n');
  const result = [];
  for (const line of lines) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
    }
  }
  return result.join('\n');
}

async function runFiles(files, options) {
  for (const file of files) {
    try {
      const source = await fs.promises.readFile(file, 'utf8');
      const j = prepareJscodeshift(options);
      const out = await transform(
        { path: file, source },
        {
          j,
          jscodeshift: j,
          stats: dry ? stats : () => {},
          report: (msg) => emitReport(file, msg),
        },
        options,
      );
      if (!out || out === source) {
        emitStatus(out ? 'nochange' : 'skip', file);
        continue;
      }
      if (print) {
        // Surface the transformed source for the parent to echo to stdout.
        emit({ event: 'print', path: file, source: out });
      }
      if (!dry) {
        // Persist atomically by writing to a sibling tempfile then renaming.
        const tmpPath = `${file}.jscodeshift-tmp-${process.pid}`;
        try {
          await fs.promises.writeFile(tmpPath, out, 'utf8');
          await fs.promises.rename(tmpPath, file);
          emitStatus('ok', file);
        } catch (err) {
          emitStatus('error', file, `File writer error: ${err && err.message || err}`);
        }
      } else {
        emitStatus('ok', file);
      }
    } catch (err) {
      emitStatus('error', file,
        `Transformation error (${String(err && err.message || err).replace(/\n/g, ' ')})\n${trimStackTrace(err && err.stack)}`);
    }
  }
}

const rl = readline.createInterface({
  input: process.stdin,
  crlfDelay: Infinity,
});

let initialised = false;
let initialisedPayload = null;
let pendingInit = null;

rl.on('line', (line) => {
  if (!line) return;
  let message;
  try {
    message = JSON.parse(line);
  } catch (err) {
    emitFatal(`failed to parse worker command: ${err.message}`);
    return;
  }
  handleMessage(message).catch((err) => emitFatal(err));
});

async function handleMessage(message) {
  if (!message || typeof message !== 'object') return;
  switch (message.type) {
    case 'init': {
      const { transform: tr, babel, parser, parserConfig, verbose: v, dry: d, print: p } = message.payload || {};
      try {
        setup(tr, babel);
        jscodeshift = require(CORE_PATH);
        verbose = v || 0;
        dry = !!d;
        print = !!p;
        initialised = true;
        if (pendingInit) {
          const resolve = pendingInit;
          pendingInit = null;
          resolve();
        } else {
          emit({ event: 'ready' });
        }
      } catch (err) {
        emitFatal(err);
        throw err;
      }
      return;
    }
    case 'files': {
      if (!initialised) {
        emitFatal('received files before init');
        return;
      }
      const files = message.files || [];
      const options = {
        parser: message.parser || initialisedPayload && initialisedPayload.parser,
        parserConfig: message.parserConfig || initialisedPayload && initialisedPayload.parserConfig,
      };
      await runFiles(files, options);
      emit({ event: 'ready' });
      return;
    }
    case 'shutdown': {
      process.exit(0);
      return;
    }
    default:
      return;
  }
}

// Fail fast if we never receive an init.
process.on('uncaughtException', (err) => {
  emitFatal(err);
  process.exit(1);
});

void CORE_PATH;
void RUNNER_PATH;"}

