                Err(_) => continue,
            };
            if !metadata.is_file() {
                continue;
            }
            let content = match fs::read_to_string(path) {
                Ok(c) => c,
                Err(_) => continue,
            };
            for line in content.split('\n') {
                let line = line.trim_end_matches('\r');
                self.add_pattern(line);
            }
        }
    }

    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let mut patterns: Vec<String> = Vec::new();
        if !val.contains('/') {
            patterns.push(format!("**/{}", val));
        } else if val.ends_with('/') {
            patterns.push(format!("**/{}**", val));
            patterns.push(format!("{}**", val));
        }
        patterns.push(val.to_string());

        for p in patterns {
            self.patterns.push(p);
        }
    }

    pub fn should_ignore<P: AsRef<Path>>(&self, path: P) -> bool {
        if self.patterns.is_empty() {
            return false;
        }
        let matcher = match self.build() {
            Ok(m) => m,
            Err(_) => return false,
        };
        let path_str = path.as_ref().to_string_lossy().to_string();
        if matcher.is_match(&path_str) {
            return true;
        }
        let normalized = strip_traversal(&path_str);
        if normalized != path_str && matcher.is_match(&normalized) {
            return true;
        }
        false
    }

    fn build(&self) -> Result<GlobSet, globset::Error> {
        let mut builder = GlobSetBuilder::new();
        for p in &self.patterns {
            if let Ok(g) = Glob::new(p) {
                builder.add(g);
            }
        }
        builder.build()
    }
}

fn strip_traversal(path: &str) -> String {
    let mut result = path.to_string();
    while result.starts_with("./") || result.starts_with("../") {
        if result.starts_with("./") {
            result = result[2..].to_string();
        } else if result.starts_with("../") {
            result = result[3..].to_string();
        }
    }
    result
}"}

