    // The Rust binary lives in the repo root; the JS package is colocated at
    // `codebase/`. The location can be overridden with `JS_CODESHIFT_DIR`.
    if let Ok(p) = std::env::var("JS_CODESHIFT_DIR") {
        return PathBuf::from(p);
    }
    let exe = std::env::current_exe().expect("current_exe");
    let mut dir = exe.parent().map(Path::to_path_buf).unwrap_or_default();

    // Strip a trailing "/release" or "/debug" segment if present, since the
    // cargo target profile is appended to CARGO_TARGET_DIR/<profile>/<bin>.
    if let Some(file_name) = dir.file_name().and_then(|n| n.to_str()) {
        if file_name == "release" || file_name == "debug" {
            if let Some(parent) = dir.parent() {
                dir = parent.to_path_buf();
            }
        }
    }

    // If the parent directory is named "target", step up one more level.
    if let Some(file_name) = dir.file_name().and_then(|n| n.to_str()) {
        if file_name == "target" {
            if let Some(parent) = dir.parent() {
                dir = parent.to_path_buf();
            }
        }
    }

    // Verify a `codebase/package.json` exists; if not, walk up the tree.
    while !dir.join("codebase").join("package.json").exists() {
        if let Some(parent) = dir.parent() {
            dir = parent.to_path_buf();
        } else {
            break;
        }
    }

    dir.push("codebase");
    dir
}"}

